<template>
  <div
    v-if="open"
    class="sp-overlay"
    :class="{ 'sp-instant': instantOpen }"
    @pointerdown="onOverlayPointerDown"
    @pointerup="onOverlayPointerUp"
    @click.self="onOverlayClick"
  >
    <div
      ref="panel"
      class="sp-panel"
      :class="{ 'sp-panel-map': mode === 'map' }"
      role="dialog"
      aria-modal="true"
      :aria-label="paletteLabel"
    >
      <div class="sp-input-row">
        <i class="fa fa-search sp-input-icon" aria-hidden="true"></i>
        <input
          ref="input"
          v-model="query"
          class="sp-input"
          type="text"
          :placeholder="inputPlaceholder"
          autocomplete="off"
          autocorrect="off"
          spellcheck="false"
          :aria-label="inputLabel"
          @compositionstart="composing = true"
          @compositionend="composing = false"
          @keydown="onInputKeydown($event)"
          @keydown.down="onArrow($event, 1)"
          @keydown.up="onArrow($event, -1)"
          @keydown.enter="onEnter($event)"
        />
        <button
          v-if="query"
          type="button"
          class="sp-clear"
          aria-label="Clear query"
          @click="clearQuery"
        >
          <i class="fas fa-times-circle" aria-hidden="true"></i>
        </button>
        <kbd class="sp-esc" @click="close">esc</kbd>
      </div>

      <div class="sp-modes">
        <div class="sp-mode-segments" role="group" aria-label="Palette mode">
          <button
            type="button"
            class="sp-mode"
            :class="{ active: mode === 'ask' }"
            :aria-pressed="(mode === 'ask').toString()"
            @click="setMode('ask')"
          >✦ Ask</button>
          <button
            type="button"
            class="sp-mode"
            :class="{ active: mode === 'search' }"
            :aria-pressed="(mode === 'search').toString()"
            @click="setMode('search')"
          >Search</button>
          <button
            type="button"
            class="sp-mode"
            :class="{ active: mode === 'map' }"
            :aria-pressed="(mode === 'map').toString()"
            @click="setMode('map')"
          >Map</button>
        </div>
        <span v-if="semStatus" class="sp-mode-status">{{ semStatus }}</span>
        <div v-if="mode === 'map'" class="sp-projection-toggle" aria-label="Map projection">
          <button
            type="button"
            class="sp-projection"
            :class="{ active: mapProjection === '2d' }"
            :aria-pressed="(mapProjection === '2d').toString()"
            @click="setMapProjection('2d')"
          >2D</button>
          <button
            type="button"
            class="sp-projection"
            :class="{ active: mapProjection === '3d' }"
            :aria-pressed="(mapProjection === '3d').toString()"
            @click="setMapProjection('3d')"
          >3D</button>
        </div>
      </div>

      <div ref="results" class="sp-results">
        <div v-if="mode === 'map'" class="sp-map">
          <EmbeddingMap
            ref="paletteMap"
            compact
            fit-stage
            :initial-view-mode="mapProjection"
            :show-controls="false"
            :show-view-toggle="false"
            :show-caption="false"
            :show-hits="false"
            @navigate="close"
          />
        </div>

        <template v-else-if="mode !== 'ask'">
          <template v-if="query.trim() && groups.length">
            <div v-for="g in groups" :key="g.page" class="sp-group">
              <div class="sp-group-label">{{ g.page }}</div>
              <button
                v-for="r in g.items"
                :key="r.flatIndex"
                class="sp-result"
                :class="{ active: r.flatIndex === activeIndex }"
                :ref="el => setRowRef(el, r.flatIndex)"
                @mousemove="activeIndex = r.flatIndex"
                @click="openResult(r, 'click')"
              >
                <span class="sp-result-title" v-html="r.titleHtml"></span>
                <span v-if="r.snippetHtml" class="sp-result-snippet" v-html="r.snippetHtml"></span>
              </button>
            </div>
          </template>

          <div v-else-if="query.trim() && semBusy" class="sp-empty">
            {{ semLoading ? 'Loading model…' : 'Searching…' }}
          </div>

          <div v-else-if="query.trim()" class="sp-empty">
            No matches for &ldquo;{{ query.trim() }}&rdquo;.
          </div>

          <div v-else class="sp-group">
            <div class="sp-group-label">Jump to</div>
            <button
              v-for="s in suggestions"
              :key="s.route"
              class="sp-result"
              @click="go(s.route, '')"
            >
              <span class="sp-result-title">{{ s.label }}</span>
            </button>
          </div>
        </template>

        <div v-else class="sp-ask">
          <div v-if="!askReady" class="sp-empty">
            Ask isn&rsquo;t set up yet. Deploy the Worker, then set the endpoint.
          </div>
          <template v-else>
            <template v-if="answerText">
              <transition
                appear
                @before-enter="beforeAnswerEnter"
                @enter="enterAnswer"
                @leave="leaveAnswer"
              >
                <p class="sp-ask-answer">{{ answerText }}</p>
              </transition>
            </template>
            <div v-else-if="askBusy" class="sp-empty">{{ askStatus }}</div>
            <div v-else-if="askError" class="sp-empty">{{ askErrorText }}</div>
            <div v-else class="sp-empty sp-ask-empty">
              <button
                type="button"
                class="sp-ask-sample"
                :class="{ visible: sampleVisible }"
                @click="useCurrentSample"
              >{{ currentSamplePrompt }}</button>
            </div>

            <div v-if="citedSources.length && !askBusy" class="sp-ask-sources">
              <div class="sp-group-label">Sources</div>
              <transition-group
                appear
                tag="div"
                class="sp-ask-source-list"
                @before-enter="beforeChipEnter"
                @enter="enterChip"
                @leave="leaveChip"
              >
                <button
                  v-for="s in citedSources"
                  :key="`${s.route}#${s.anchor || ''}`"
                  :data-source-key="`${s.route}#${s.anchor || ''}`"
                  class="sp-ask-source"
                  :class="{ 'is-previewed': hoveredSourceId === `${s.route}#${s.anchor || ''}` }"
                  @mouseenter="hoveredSourceId = `${s.route}#${s.anchor || ''}`"
                  @mouseleave="hoveredSourceId = null"
                  @focus="hoveredSourceId = `${s.route}#${s.anchor || ''}`"
                  @blur="hoveredSourceId = null"
                  @click="openAskSource(s)"
                >{{ s.page }} › {{ s.displayTitle }}</button>
              </transition-group>
            </div>

            <div v-if="askFollowUpQuestions.length && answerText && !askBusy" class="sp-ask-followups">
              <div class="sp-group-label">Keep exploring</div>
              <div class="sp-ask-followup-list">
                <button
                  v-for="q in askFollowUpQuestions"
                  :key="q"
                  type="button"
                  class="sp-ask-followup"
                  @click="askFollowUp(q)"
                >{{ q }}</button>
              </div>
            </div>
          </template>
        </div>
      </div>

      <!-- Hover preview floats above the panel content (and never pushes the
           layout): it is positioned against the panel and follows the hovered
           source chip, recomputed on results scroll. -->
      <transition name="sp-preview-fade">
        <div
          v-if="askSourcePreview"
          :key="askSourcePreview.id"
          class="sp-ask-preview"
          :style="previewStyle"
        >
          <span class="sp-ask-preview-kicker">{{ askSourcePreview.page }} › {{ askSourcePreview.title }}</span>
          <p class="sp-ask-preview-text">{{ askSourcePreview.snippet }}</p>
        </div>
      </transition>

      <div class="sp-foot">
        <span><kbd>⌥</kbd> mode</span>
        <span><kbd>&crarr;</kbd> {{ mode === 'ask' ? 'ask' : (mode === 'map' ? 'place' : 'open') }}</span>
        <span v-if="mode === 'search'"><kbd>&uarr;</kbd><kbd>&darr;</kbd> move</span>
        <span><kbd>esc</kbd> close</span>
      </div>
    </div>
  </div>
</template>

<script>
import Fuse from 'fuse.js';
import EmbeddingMap from './EmbeddingMap.vue';
import { animate } from 'motion';
import { ensureReady, semanticRank } from '../utils/semanticSearch';
import { askConfigured, askStream, askErrorMessage } from '../utils/askSite';
import { ASK_SAMPLE_PROMPTS } from '../utils/askPrompts';
import {
  allAskContexts,
  askAnswerFollowUps,
  citedSourcesFromAnswer,
  cleanAskAnswer,
  cleanAskContextText,
  groundAskFollowUps,
  sourceDisplayTitle,
  takeRetrievalTrace,
} from '../utils/askRetrieval';
import {
  logAskClient,
  logEvent,
  logSearch,
  logSearchClick,
  newAskContext,
  newId,
} from '../utils/askTelemetry';

function slugify(s) {
  let out = '';
  let lastDash = true;
  const text = String(s).replace(/<[^>]+>/g, '').toLowerCase().trim();
  for (const c of text) {
    const ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_';
    if (ok) {
      out += c;
      lastDash = false;
    } else if (!lastDash) {
      out += '-';
      lastDash = true;
    }
  }
  while (out.endsWith('-')) out = out.slice(0, -1);
  return out.slice(0, 80);
}

function holdAtTop(target) {
  let live = true;
  const reSnap = () => { if (live && target.isConnected) target.scrollIntoView({ behavior: 'auto', block: 'start' }); };
  const stop = () => {
    live = false;
    window.removeEventListener('wheel', stop);
    window.removeEventListener('touchstart', stop);
    window.removeEventListener('keydown', stop);
  };
  window.addEventListener('wheel', stop, { passive: true });
  window.addEventListener('touchstart', stop, { passive: true });
  window.addEventListener('keydown', stop);
  const root = document.querySelector('.content-container') || document;
  [...root.querySelectorAll('img')].filter(im => !im.complete).forEach(im => {
    im.addEventListener('load', reSnap, { once: true });
    im.addEventListener('error', reSnap, { once: true });
  });
  [150, 400, 800, 1300, 1900].forEach(t => setTimeout(reSnap, t));
  setTimeout(stop, 2400);
}

const STOP = new Set([
  'the', 'a', 'an', 'of', 'on', 'in', 'to', 'is', 'are', 'was', 'were', 'be',
  'and', 'or', 'for', 'with', 'at', 'by', 'from', 'as', 'it', 'i', 'my', 'me',
  'this', 'that', 'how', 'what', 'we', 'you', 'they', 'but', 'so', 'if', 'into',
  'about', 'out', 'up', 'over', 'than', 'then', 'has', 'have', 'had', 'do',
]);


export default {
  name: 'SearchPalette',
  components: { EmbeddingMap },
  data() {
    return {
      open: false,
      instantOpen: false,
      query: '',
      savedQueries: { search: '', ask: '', map: '' },
      mapProjection: '2d',
      items: [],
      fuse: null,
      loaded: false,
      activeIndex: 0,
      rowRefs: {},
      composing: false,
      mode: 'ask',
      semHits: [],
      semLoading: false,
      semQuerying: false,
      semError: '',
      askAnswer: '',
      askSources: [],
      askBusy: false,
      askError: '',
      askStatus: '',
      hoveredSourceId: null,
      previewStyle: null,
      groundedFollowUps: null,
      overlayPointerStartedOutside: false,
      overlayPointerEndedOutside: false,
      sampleVisible: true,
      sampleIndex: Math.floor(Math.random() * ASK_SAMPLE_PROMPTS.length),
      samplePrompts: ASK_SAMPLE_PROMPTS,
      suggestions: [
        { label: 'About', route: '/about' },
        { label: 'Education', route: '/education' },
        { label: 'Experience', route: '/experience' },
        { label: 'Research', route: '/research' },
        { label: 'Projects', route: '/projects' },
        { label: 'Fragments', route: '/fragments' },
        { label: 'CV', route: '/cv' },
      ],
    };
  },
  computed: {
    askErrorText() {
      return askErrorMessage();
    },
    itemsById() {
      const m = {};
      for (const it of this.items) m[it.id] = it;
      return m;
    },
    semBusy() {
      return this.semLoading || this.semQuerying;
    },
    semStatus() {
      if (this.mode === 'map') return '';
      if (this.semError) return 'offline';
      if (this.semLoading) return 'loading model…';
      return '';
    },
    paletteLabel() {
      if (this.mode === 'ask') return 'Ask this site';
      if (this.mode === 'map') return 'Map the site';
      return 'Search the site';
    },
    inputLabel() {
      if (this.mode === 'ask') return 'Ask question';
      if (this.mode === 'map') return 'Map query';
      return 'Search query';
    },
    inputPlaceholder() {
      if (this.mode === 'ask') return 'Ask anything about Henry...';
      if (this.mode === 'map') return 'Drop a question into the map...';
      return 'Search the site...';
    },
    askReady() {
      return askConfigured();
    },
    answerText() {
      return cleanAskAnswer(this.askAnswer);
    },
    citedSources() {
      const seen = new Set();
      const out = [];
      for (const source of citedSourcesFromAnswer(this.askAnswer, this.askSources)) {
        const key = `${source.route}#${source.anchor || ''}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({
          ...source,
          displayTitle: this.askDisplayTitle(source),
        });
      }
      return out;
    },
    // Hovering a cited source peeks at its passage without leaving the panel.
    askSourcePreview() {
      if (!this.hoveredSourceId) return null;
      const s = this.citedSources.find(
        (x) => `${x.route}#${x.anchor || ''}` === this.hoveredSourceId,
      );
      if (!s) return null;
      const text = cleanAskContextText(s.body || '').replace(/\s+/g, ' ').trim();
      const snippet = text
        ? (text.length > 220 ? `${text.slice(0, 220).trim()}…` : text)
        : 'Open the passage to read it.';
      return { id: this.hoveredSourceId, page: s.page, title: s.displayTitle, snippet };
    },
    // Next questions for the Ask mode: the model's own suggestions first, then
    // a hand-picked mix so the row is never empty.
    askFollowUpQuestions() {
      if (this.askBusy || !this.answerText) return [];
      const rawAiFollowUps = askAnswerFollowUps(this.askAnswer);
      if (this.groundedFollowUps !== null) {
        if (this.groundedFollowUps.length) return this.groundedFollowUps;
      } else if (rawAiFollowUps.length) {
        return rawAiFollowUps;
      }
      const current = String(this.query || '').trim().toLowerCase();
      const candidates = [];
      for (const s of this.citedSources) {
        const t = String(s.displayTitle || s.title || '').trim();
        if (t) candidates.push(`Tell me more about ${t}`);
      }
      for (const p of this.samplePrompts) candidates.push(p);
      const seen = new Set();
      const out = [];
      for (const c of candidates) {
        const k = String(c).trim().toLowerCase();
        if (!k || k === current || seen.has(k)) continue;
        seen.add(k);
        out.push(String(c).trim());
        if (out.length >= 3) break;
      }
      return out;
    },
    currentSamplePrompt() {
      return this.samplePrompts[this.sampleIndex] || '';
    },
    results() {
      if (this.mode === 'ask') return [];
      const q = this.query.trim();
      if (!q) return [];
      const seen = new Set();
      const out = [];
      for (const id of this.hybridIds(q)) {
        const item = this.itemsById[id];
        if (!item) continue;
        const key = `${item.route}#${item.anchor || ''}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push(item);
        if (out.length >= 12) break;
      }
      return out;
    },
    groups() {
      const out = [];
      const byPage = new Map();
      for (const item of this.results) {
        const body = this.searchDisplayBody(item.body);
        const titleHtml = this.highlight(this.displayTitle(item));
        const snippetHtml = this.snippet(body) || this.leadSnippet(body);
        const row = { ...item, titleHtml, snippetHtml };
        if (!byPage.has(item.page)) {
          const g = { page: item.page, items: [] };
          byPage.set(item.page, g);
          out.push(g);
        }
        byPage.get(item.page).items.push(row);
      }
      let fi = 0;
      for (const group of out) {
        for (const item of group.items) item.flatIndex = fi++;
      }
      return out;
    },
    flatList() {
      return this.groups.flatMap(g => g.items);
    },
  },
  watch: {
    query() {
      this.activeIndex = 0;
      if (this.mode === 'search' && this.query.trim()) {
        this.warmSemantic();
        this.scheduleSemantic();
        this.scheduleSearchLog();
      }
    },
    semHits() {
      if (this.mode === 'search' && this.query.trim()) this.scheduleSearchLog();
    },
    hoveredSourceId() {
      // The chip just gained/lost hover: position the floating preview against
      // the chip once the DOM has settled, or clear it.
      this.$nextTick(this.updateAskPreviewPosition);
    },
  },
  mounted() {
    this._semSeq = 0;
    this._askSeq = 0;
    this._openedAt = 0;
    this._searchId = null;
    this._searchAt = 0;
    this._loggedSearchQuery = '';
    this._lastAskEventId = null;
    this._spAnims = new Set();
    this._sampleTimer = window.setInterval(this.rotateSample, 3200);
    window.addEventListener('keydown', this.onKey);
    // Any scroll gesture invalidates the hover anchor: drop the preview at
    // once instead of letting it float at a stale position. Capture phase
    // catches scrolls from the results container too (scroll does not bubble).
    this._onAnyScroll = () => {
      if (this.hoveredSourceId) this.hoveredSourceId = null;
    };
    window.addEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
    this._onWindowResize = () => {
      if (this.hoveredSourceId) this.updateAskPreviewPosition();
    };
    window.addEventListener('resize', this._onWindowResize, { passive: true });
  },
  unmounted() {
    if (this._spAnims) {
      this._spAnims.forEach((animation) => animation.stop());
      this._spAnims.clear();
    }
    window.removeEventListener('keydown', this.onKey);
    window.removeEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
    window.removeEventListener('resize', this._onWindowResize, { passive: true });
    window.clearInterval(this._sampleTimer);
    window.clearTimeout(this._sampleFadeTimer);
    window.clearTimeout(this._searchLogTimer);
    this.unlockScroll();
  },
  methods: {
    // The hover preview floats above the panel: anchor it to the hovered chip
    // in panel coordinates, flip above when there is no room below, and never
    // participate in layout.
    updateAskPreviewPosition() {
      if (!this.hoveredSourceId) {
        this.previewStyle = null;
        return;
      }
      const panel = this.$refs.panel;
      const chip = panel && panel.querySelector(`.sp-ask-source[data-source-key="${this.hoveredSourceId}"]`);
      if (!panel || !chip) return;
      const pr = panel.getBoundingClientRect();
      const cr = chip.getBoundingClientRect();
      const gap = 8;
      const left = Math.max(12, cr.left - pr.left);
      const width = Math.max(200, Math.min(340, pr.right - Math.max(pr.left + 12, cr.left) - 12));
      const below = cr.bottom - pr.top + gap;
      const above = pr.bottom - cr.top + gap;
      // Rough preview height; flip above the chip when the space below is short.
      const estHeight = 220;
      if (cr.bottom + gap + estHeight > pr.bottom && above > estHeight) {
        this.previewStyle = {
          left: `${left}px`,
          bottom: `${Math.max(12, above)}px`,
          width: `${width}px`,
        };
      } else {
        this.previewStyle = {
          left: `${left}px`,
          top: `${Math.min(below, Math.max(12, pr.bottom - 12))}px`,
          width: `${width}px`,
        };
      }
    },
    reduceMotion() {
      return window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    },
    trackAnim(animation) {
      if (!this._spAnims) this._spAnims = new Set();
      this._spAnims.add(animation);
      return animation;
    },
    untrackAnim(animation) {
      if (this._spAnims) this._spAnims.delete(animation);
    },
    // The streamed answer fades/settles in once, when the first tokens arrive,
    // so the text reads as "forming" rather than appearing out of nowhere.
    beforeAnswerEnter(el) {
      el.style.opacity = '0';
      el.style.transform = 'translateY(6px)';
    },
    enterAnswer(el, done) {
      if (this.reduceMotion()) {
        el.style.opacity = '';
        el.style.transform = '';
        done();
        return;
      }
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        el.style.opacity = '';
        el.style.transform = '';
        this.untrackAnim(animation);
        done();
      };
      const animation = this.trackAnim(animate(el, {
        opacity: [0, 1],
        transform: ['translateY(6px)', 'translateY(0px)'],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.4,
        onComplete: finish,
      }));
      // Safety net: never leave the answer invisible if the spring stalls.
      window.setTimeout(finish, 1000);
    },
    leaveAnswer(el, done) {
      if (this.reduceMotion()) {
        done();
        return;
      }
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        this.untrackAnim(animation);
        done();
      };
      const animation = this.trackAnim(animate(el, {
        opacity: [1, 0],
        transform: ['translateY(0px)', 'translateY(-4px)'],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.18,
        onComplete: finish,
      }));
      window.setTimeout(finish, 400);
    },
    // Citation chips spring in with a small stagger once the answer settles.
    beforeChipEnter(el) {
      el.style.opacity = '0';
      el.style.transform = 'translateY(4px)';
    },
    enterChip(el, done) {
      if (this.reduceMotion()) {
        el.style.opacity = '';
        el.style.transform = '';
        done();
        return;
      }
      const index = Math.max(0, Array.from(el.parentNode ? el.parentNode.children : []).indexOf(el));
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        el.style.opacity = '';
        el.style.transform = '';
        this.untrackAnim(animation);
        done();
      };
      const animation = this.trackAnim(animate(el, {
        opacity: [0, 1],
        transform: ['translateY(4px)', 'translateY(0px)'],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.3,
        delay: index * 0.045,
        onComplete: finish,
      }));
      window.setTimeout(finish, 1000);
    },
    leaveChip(el, done) {
      if (this.reduceMotion()) {
        done();
        return;
      }
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        this.untrackAnim(animation);
        done();
      };
      const animation = this.trackAnim(animate(el, {
        opacity: [1, 0],
        transform: ['translateY(0px)', 'translateY(-2px)'],
      }, {
        type: 'spring',
        bounce: 0,
        duration: 0.12,
        onComplete: finish,
      }));
      window.setTimeout(finish, 400);
    },
    onOverlayPointerDown(e) {
      this.overlayPointerStartedOutside = !this.isInsidePanel(e.target);
      this.overlayPointerEndedOutside = false;
    },
    onOverlayPointerUp(e) {
      this.overlayPointerEndedOutside = !this.isInsidePanel(e.target);
    },
    onOverlayClick(e) {
      if (this.overlayPointerStartedOutside && this.overlayPointerEndedOutside) {
        this.close();
      } else {
        e.preventDefault();
        e.stopPropagation();
      }
      this.overlayPointerStartedOutside = false;
      this.overlayPointerEndedOutside = false;
    },
    isInsidePanel(target) {
      return !!(target && target.closest && target.closest('.sp-panel'));
    },
    onKey(e) {
      const k = e.key.toLowerCase();
      if ((e.metaKey || e.ctrlKey) && k === 'k') {
        e.preventDefault();
        this.toggle('shortcut');
      } else if (e.key === 'Escape' && this.open) {
        this.close();
      } else if (e.key === '/' && !this.open && !this.isTyping(e)) {
        e.preventDefault();
        this.openPalette('shortcut');
      }
    },
    isTyping(e) {
      const t = e.target;
      return t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable);
    },
    async loadIndex() {
      if (this.loaded) return;
      try {
        const res = await fetch('/assets/search-index.json', { cache: 'no-cache' });
        this.items = await res.json();
        this.fuse = new Fuse(this.items, {
          keys: [{ name: 'title', weight: 0.7 }, { name: 'body', weight: 0.3 }],
          threshold: 0.3,
          ignoreLocation: true,
          minMatchCharLength: 2,
        });
        this.loaded = true;
      } catch (err) {
        console.error('search index load failed:', err);
      }
    },
    toggle(via = 'shortcut') {
      this.open ? this.close() : this.openPalette(via);
    },
    openPalette(via = 'shortcut') {
      this.instantOpen = via === 'shortcut';
      this.open = true;
      this.markOpened(via);
      this.sampleVisible = true;
      this.loadIndex();
      this.lockScroll();
      this.warmSemantic();
      this.$nextTick(() => this.$refs.input && this.$refs.input.focus());
    },
    markOpened(via) {
      this._openedAt = Date.now();
      logEvent('palette_open', { via, mode: this.mode });
    },
    openAsk(prefill) {
      this.instantOpen = false;
      this.open = true;
      this.markOpened(prefill ? 'prefill' : 'ask_button');
      this.sampleVisible = true;
      this.loadIndex();
      this.lockScroll();
      this.mode = 'ask';
      this.activeIndex = 0;
      this.askAnswer = '';
      this.askSources = [];
      this.askError = '';
      this.warmSemantic();
      if (prefill && prefill.trim()) {
        this.query = prefill.trim();
        this.$nextTick(() => this.askQuestion());
      } else {
        this.query = '';
        this.$nextTick(() => this.$refs.input && this.$refs.input.focus());
      }
    },
    close() {
      this.open = false;
      this.unlockScroll();
    },
    move(dir) {
      const n = this.flatList.length;
      if (!n) return;
      this.activeIndex = (this.activeIndex + dir + n) % n;
      this.$nextTick(() => {
        const el = this.rowRefs[this.activeIndex];
        if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest' });
      });
    },
    isComposing(e) {
      return this.composing || e.isComposing || e.keyCode === 229;
    },
    onEnter(e) {
      if (this.isComposing(e)) return;
      e.preventDefault();
      if (this.mode === 'ask') this.askQuestion();
      else if (this.mode === 'map') this.placeMapQuery();
      else this.choose();
    },
    onArrow(e, dir) {
      if (this.isComposing(e)) return;
      e.preventDefault();
      this.move(dir);
    },
    onInputKeydown(e) {
      if (this.isComposing(e)) return;
      if (e.key !== 'Alt' || e.repeat) return;
      e.preventDefault();
      this.cycleMode();
    },
    cycleMode() {
      const modes = ['ask', 'search', 'map'];
      const i = modes.indexOf(this.mode);
      this.setMode(modes[(i + 1) % modes.length]);
    },
    choose() {
      const target = this.flatList[this.activeIndex];
      if (target) this.openResult(target, 'enter');
    },
    // Log a search only once the query settles, so typing "melbourne" produces
    // one row rather than nine. Re-fires when the semantic leg lands late.
    scheduleSearchLog() {
      window.clearTimeout(this._searchLogTimer);
      this._searchLogTimer = window.setTimeout(() => this.reportSearch(), 900);
    },
    reportSearch() {
      const q = this.query.trim();
      if (!q || this.mode !== 'search' || this.semBusy) return;
      if (this._loggedSearchQuery === q) return;
      this._loggedSearchQuery = q;
      this._searchId = newId();
      this._searchAt = Date.now();

      const semById = new Map(this.semHits.map((h, i) => [h.id, { rank: i + 1, score: h.score }]));
      const lex = this.fuse ? this.fuse.search(q).slice(0, 20).map(r => r.item.id) : [];
      const lexById = new Map(lex.map((id, i) => [id, i + 1]));
      logSearch({
        search_id: this._searchId,
        surface: 'palette',
        query: q,
        n_results: this.results.length,
        n_lex: lex.length,
        n_sem: this.semHits.length,
        sem_top_score: this.semHits.length ? Number(this.semHits[0].score.toFixed(5)) : null,
        sem_error: this.semError || null,
        ms_since_open: this._openedAt ? Date.now() - this._openedAt : null,
        results: this.results.map((item, i) => ({
          chunk_id: String(item.id),
          route: item.route,
          anchor: item.anchor || null,
          page: item.page,
          rank: i + 1,
          lex_rank: lexById.get(item.id) || null,
          sem_rank: semById.get(item.id) ? semById.get(item.id).rank : null,
          sem_score: semById.get(item.id) ? Number(semById.get(item.id).score.toFixed(5)) : null,
        })),
      });
    },
    openResult(item, via) {
      const rank = this.results.findIndex(r => r.id === item.id) + 1;
      logSearchClick({
        search_id: this._searchId || null,
        query: this.query.trim(),
        chunk_id: String(item.id),
        route: item.route,
        anchor: item.anchor || null,
        rank: rank || null,
        via,
        ms_to_click: this._searchAt ? Date.now() - this._searchAt : null,
      });
      this.go(item.route, item.anchor);
    },
    openAskSource(source) {
      logEvent('ask_source_click', {
        chunk_id: source.chunk_id || null,
        route: source.route,
        anchor: source.anchor || null,
        title: source.displayTitle || source.title || null,
        surface: 'palette',
      }, this._lastAskEventId || null);
      this.go(source.route, source.anchor);
    },
    setRowRef(el, i) {
      if (el) this.rowRefs[i] = el;
      else delete this.rowRefs[i];
    },
    go(route, anchor) {
      const samePage = this.$route.path === route;
      const isFragmentAnchor = route === '/fragments' && anchor;
      this.close();

      if (isFragmentAnchor) {
        this.$router.push({ path: route, hash: `#${anchor}` }).catch(() => {});
      } else if (!samePage) {
        this.$router.push(route).catch(() => {});
      }

      this.$nextTick(() => this.scrollTo(anchor, 0, samePage));
    },
    scrollTo(anchor, attempt, samePage) {
      this.assignAnchors();
      if (!anchor) {
        window.scrollTo({ top: 0, behavior: samePage ? 'smooth' : 'auto' });
        return;
      }
      const el = document.getElementById(anchor);
      if (el) {
        const target = this.scrollTargetFor(el);
        target.scrollIntoView({ behavior: samePage ? 'smooth' : 'auto', block: 'start' });
        this.flash(el);
        if (!samePage) holdAtTop(target);
        return;
      }
      if (attempt < 25) setTimeout(() => this.scrollTo(anchor, attempt + 1, samePage), 120);
    },
    scrollTargetFor(el) {
      const te = el.closest('.timeline-event');
      if (te) return te;
      if (el.matches && el.matches('li.title')) {
        const sec = el.closest('section');
        if (sec) return sec;
      }
      return el;
    },
    assignAnchors() {
      const root = document.querySelector('.content-container');
      if (!root) return;
      const useEntries = !!root.querySelector('li.title');
      const els = useEntries ? root.querySelectorAll('li.title') : root.querySelectorAll('h2, h3');
      const seen = new Set();
      els.forEach(el => {
        const base = slugify(el.textContent);
        if (!base) return;
        let slug = base;
        let n = 2;
        while (seen.has(slug)) slug = `${base}-${n++}`;
        seen.add(slug);
        el.id = slug;
      });
    },
    flash(el) {
      el.classList.add('search-flash');
      setTimeout(() => el.classList.remove('search-flash'), 1700);
    },
    lockScroll() {
      this._prevOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
    },
    unlockScroll() {
      document.body.style.overflow = this._prevOverflow || '';
    },
    escapeHtml(s) {
      return String(s)
        .split('&').join('&amp;')
        .split('<').join('&lt;')
        .split('>').join('&gt;')
        .split(String.fromCharCode(34)).join('&quot;');
    },
    escapeRegExp(text) {
      return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    },
    words(text) {
      const out = [];
      let word = '';
      for (const c of String(text).toLowerCase()) {
        const ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_';
        if (ok) word += c;
        else if (word) { out.push(word); word = ''; }
      }
      if (word) out.push(word);
      return out;
    },
    tokens() {
      const all = this.words(this.query).filter(t => t.length >= 2);
      const meaningful = all.filter(t => !STOP.has(t));
      return meaningful.length ? meaningful : all;
    },
    highlight(text) {
      const escaped = this.escapeHtml(text);
      const terms = [...new Set(this.tokens())]
        .sort((a, b) => b.length - a.length)
        .map((term) => this.escapeRegExp(term));
      if (!terms.length) return escaped;

      const re = new RegExp(`(${terms.join('|')})`, 'gi');
      return escaped.replace(re, '<mark>$1</mark>');
    },
    displayTitle(item) {
      return sourceDisplayTitle(item);
    },
    askDisplayTitle(item) {
      return sourceDisplayTitle(item);
    },
    searchDisplayBody(body) {
      return String(body || '')
        .replace(/\bEnglish summary:\s*/g, '')
        .replace(/中文摘要:\s*/g, '')
        .replace(/\bEnglish full text:\s*/g, '')
        .replace(/中文全文:\s*/g, '')
        .trim();
    },
    askContextText(source) {
      let text = cleanAskContextText(source.body);
      if (source.route !== '/fragments') return text;
      return this.searchDisplayBody(text);
    },
    snippet(body) {
      const lower = body.toLowerCase();
      let pos = -1;
      for (const t of [...this.tokens()].sort((a, b) => b.length - a.length)) {
        const found = lower.indexOf(t);
        if (found >= 0) { pos = found; break; }
      }
      if (pos < 0) return '';
      const start = Math.max(0, pos - 40);
      let s = body.slice(start, start + 170);
      if (start > 0) s = `…${s}`;
      if (start + 170 < body.length) s = `${s}…`;
      return this.highlight(s);
    },
    leadSnippet(body) {
      let s = body.slice(0, 170);
      if (body.length > 170) s = `${s}…`;
      return this.highlight(s);
    },
    setMode(m) {
      if (this.mode === m) return;
      logEvent('palette_mode', { from: this.mode, to: m });
      this.savedQueries[this.mode] = this.query;
      this.mode = m;
      this.query = this.savedQueries[m] || '';
      this.activeIndex = 0;
      this.sampleVisible = true;
      if (m === 'search') {
        if (this.query.trim()) { this.warmSemantic(); this.scheduleSemantic(); }
      } else if (m === 'ask') {
        this.warmSemantic();
      } else {
        this.$nextTick(() => {
          if (this.query.trim()) this.placeMapQuery();
        });
      }
    },
    clearQuery() {
      this.query = '';
      if (this.mode === 'ask') {
        this.askAnswer = '';
        this.askSources = [];
        this.askError = '';
        this.groundedFollowUps = null;
      }
      this.$nextTick(() => this.$refs.input && this.$refs.input.focus());
    },
    placeMapQuery() {
      const map = this.$refs.paletteMap;
      if (map && map.placeQuery) map.placeQuery(this.query);
    },
    setMapProjection(mode) {
      this.mapProjection = mode;
      const map = this.$refs.paletteMap;
      if (map && map.setViewMode) map.setViewMode(mode);
    },
    useCurrentSample() {
      this.query = this.currentSamplePrompt;
      this.$nextTick(() => this.$refs.input && this.$refs.input.focus());
    },
    askFollowUp(q) {
      const question = String(q || '').trim();
      if (!question) return;
      this.query = question;
      this.hoveredSourceId = null;
      logEvent('ask_followup_click', { question, surface: 'palette' }, this._lastAskEventId || null);
      this.$nextTick(() => this.$refs.input && this.$refs.input.focus());
      this.askQuestion();
    },
    nextRandomSampleIndex() {
      const count = this.samplePrompts.length;
      if (count <= 1) return this.sampleIndex;

      let next = Math.floor(Math.random() * (count - 1));
      if (next >= this.sampleIndex) next += 1;
      return next;
    },
    rotateSample() {
      if (!this.open || this.mode !== 'ask' || this.query.trim() || this.answerText || this.askBusy || this.askError) return;
      this.sampleVisible = false;
      window.clearTimeout(this._sampleFadeTimer);
      this._sampleFadeTimer = window.setTimeout(() => {
        this.sampleIndex = this.nextRandomSampleIndex();
        this.$nextTick(() => { this.sampleVisible = true; });
      }, 260);
    },
    async askQuestion() {
      const q = this.query.trim();
      if (!q || !this.askReady) return;
      const seq = ++this._askSeq;
      this.askBusy = true;
      this.askError = '';
      this.askAnswer = '';
      this.askSources = [];
      this.groundedFollowUps = null;

      const telemetry = newAskContext('palette');
      this._lastAskEventId = telemetry.event_id;
      const startedAt = Date.now();
      let firstTokenAt = null;
      let trace = null;
      let payloadLength = 0;
      let payloadChars = 0;
      let failure = '';
      // Local copies: a newer question resets the component state, and the
      // superseded ask still deserves an accurate row.
      let answer = '';
      let sources = [];

      try {
        this.askStatus = 'Thinking…';
        const contexts = (await allAskContexts(q, this.items))
          .map(source => ({
            ...source,
            text: this.askContextText(source),
          }))
          .filter(source => source.text);
        trace = takeRetrievalTrace();
        sources = contexts;
        if (seq !== this._askSeq) return;
        this.askSources = contexts;
        const payload = contexts.map(c => ({
          page: c.page,
          title: this.askDisplayTitle(c),
          text: c.text,
        }));
        payloadLength = payload.length;
        payloadChars = payload.reduce((sum, c) => sum + c.text.length, 0);
        const stream = askStream(q, payload, {
          meta: {
            event_id: telemetry.event_id,
            session_id: telemetry.session_id,
            turn_index: telemetry.turn_index,
            surface: telemetry.surface,
          },
          onFirstToken: () => { firstTokenAt = Date.now(); },
        });
        for await (const tok of stream) {
          if (seq !== this._askSeq) return;
          answer += tok;
          this.askAnswer += tok;
        }
        if (seq === this._askSeq) this.groundAiFollowUps(seq);
      } catch (e) {
        failure = String(e?.message || e).slice(0, 200);
        if (seq === this._askSeq) this.askError = 'error';
        console.error('ask failed:', e);
      } finally {
        if (seq === this._askSeq) this.askBusy = false;
        this.reportAsk(telemetry, {
          question: q,
          answer,
          sources,
          startedAt,
          firstTokenAt,
          trace,
          payloadLength,
          payloadChars,
          failure,
          aborted: seq !== this._askSeq,
        });
      }
    },
    async groundAiFollowUps(seq) {
      const questions = askAnswerFollowUps(this.askAnswer);
      if (!questions.length) {
        if (seq === this._askSeq) this.groundedFollowUps = [];
        return;
      }
      const grounded = await groundAskFollowUps(questions);
      if (seq !== this._askSeq) return;
      this.groundedFollowUps = grounded;
    },
    // One row per question describing what the browser saw: ranking internals,
    // timings, and which sources the model actually cited.
    reportAsk(telemetry, info) {
      const finishedAt = Date.now();
      const cited = info.answer
        ? citedSourcesFromAnswer(info.answer, info.sources).map(s => ({
          n: s.n,
          chunk_id: s.chunk_id,
          route: s.route,
          anchor: s.anchor || null,
          title: this.askDisplayTitle(s),
        }))
        : [];
      logAskClient(telemetry, {
        question: info.question,
        retrieval_ms: info.trace ? info.trace.retrieval_ms : null,
        ttft_ms: info.firstTokenAt ? info.firstTokenAt - info.startedAt : null,
        stream_ms: info.firstTokenAt ? finishedAt - info.firstTokenAt : null,
        total_ms: finishedAt - info.startedAt,
        answer_len: info.answer.length,
        aborted: info.aborted,
        error: info.failure || null,
        n_contexts_sent: info.payloadLength,
        contexts_chars: info.payloadChars,
        n_lex: info.trace ? info.trace.n_lex : null,
        n_sem: info.trace ? info.trace.n_sem : null,
        sem_top_score: info.trace ? info.trace.sem_top_score : null,
        cited,
        retrieval: info.trace ? info.trace.rows : [],
      });
    },
    hybridIds(q) {
      const K = 60;
      const W_LEX = 2;
      const W_SEM = 1;
      const score = new Map();
      const add = (ids, w) => ids.forEach((id, i) => score.set(id, (score.get(id) || 0) + w / (K + i)));
      if (this.fuse) add(this.fuse.search(q).slice(0, 20).map(r => r.item.id), W_LEX);
      add(this.semHits.map(h => h.id), W_SEM);
      return [...score.entries()].sort((a, b) => b[1] - a[1]).map(([id]) => id);
    },
    async warmSemantic() {
      if (this._semWarmed || this.semLoading) return;
      this.semLoading = true;
      this.semError = '';
      try {
        await ensureReady();
        this._semWarmed = true;
      } catch (e) {
        this.semError = 'offline';
        console.error('semantic warm-up failed:', e);
      } finally {
        this.semLoading = false;
      }
    },
    scheduleSemantic() {
      clearTimeout(this._semDebounce);
      this._semDebounce = setTimeout(() => this.runSemantic(), 250);
    },
    async runSemantic() {
      const q = this.query.trim();
      if (!q) { this.semHits = []; return; }
      const seq = ++this._semSeq;
      this.semQuerying = true;
      try {
        const hits = await semanticRank(q, 12);
        if (seq === this._semSeq) { this.semHits = hits; this.semError = ''; }
      } catch (e) {
        if (seq === this._semSeq) { this.semHits = []; this.semError = 'offline'; }
        console.error('semantic search failed:', e);
      } finally {
        if (seq === this._semSeq) this.semQuerying = false;
      }
    },
  },
};
</script>

